// CSD_RATIONALE_BEGIN
// This constrained decoding strategy solves math word problems step by step, writing each arithmetic computation inside << >> delimiters.
// It uses two phases: an unconstrained phase where it generates tokens without grammar constraints, and a constrained phase where it adheres to grammar rules.
// During the unconstrained phase, it penalizes ">>" to encourage longer chains before "<<" triggers.
// During the constrained phase, it uses ConfidenceGatedStep to ensure that the model only constrains when necessary, allowing it to sample freely when appropriate.
// The strategy ends when the end-of-sequence token (eosToken) is generated or the maximum number of steps (maxSteps) is reached.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    lm.GenerateLogits(prompt + generated);
    helpers.PenalizeTokenLogits(lm, [">>"], 5.0);
    var next := lm.ChooseNextTokenUnconstrained();
    helpers.cost := helpers.cost + 1;
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
    }
  } else {
    var next, wasConstrained := helpers.ConfidenceGatedStep(lm, parser, prompt, currentConstrained);
    generated := generated + [next];
    steps := steps + 1;
    if wasConstrained {
      currentConstrained := currentConstrained + [next];
      if Contains(next, ">>") { insideConstrained := false; }
    } else {
      insideConstrained := false;
    }
  }
}
cost := helpers.cost;

